<?php
declare(strict_types=1);
/** Original Blueprint p72/p74/p164/p234: native local gates, never paid-order certification. */
final class OfflineListingOrderLineageTest extends WP_UnitTestCase {
 protected function setUp():void {parent::setUp();DigiForge\Core\Activator::activate();DigiForge\Core\Settings::protectProduction();add_action('digiforge_log',[DigiForge\Security\Logger::class,'write'],10,4);wp_set_current_user(self::factory()->user->create(['role'=>'administrator']));}
 private function version(string $shop):array {
  $research=new DigiForge\Research\Repository();$source=$research->createSource(['shop_key'=>$shop,'name'=>'Offline lineage source','source_type'=>'manual','environment'=>'sandbox']);self::assertNotWPError($source);$observation=$research->ingest(['source_id'=>$source['id'],'title'=>'Local lifecycle fixture','body'=>'Synthetic local fixture, no marketplace claim.']);self::assertNotWPError($observation);$evidence=$research->addEvidence((int)$observation['id'],['evidence_type'=>'manual_note','value'=>'Offline fixture only.']);self::assertNotWPError($evidence);$candidate=$research->createCandidate(['shop_key'=>$shop,'title'=>'Offline lineage '.$shop]);self::assertNotWPError($candidate);self::assertTrue($research->linkEvidence((int)$candidate['id'],(int)$evidence['id']));self::assertNotWPError($research->review((int)$candidate['id'],'APPROVED','Synthetic fixture review only.'));$opportunity=$research->promote((int)$candidate['id']);self::assertNotWPError($opportunity);
  $products=new DigiForge\ProductFactory\Repository();$family=$products->create('product_family',['opportunity_id'=>$opportunity['id'],'name'=>'Offline family']);self::assertNotWPError($family);$product=$products->create('product',['product_family_id'=>$family['id'],'name'=>'Offline product']);self::assertNotWPError($product);$notes=['spec'=>['listing_title_draft'=>'Offline original local artwork','listing_description_draft'=>'Deterministic synthetic acceptance fixture, not a live sale.','seo_keywords'=>['offline','fixture'],'price_strategy'=>['recommended_etsy_price_usd'=>12],'delivery_selection'=>['selected_language'=>'English']]];$version=$products->create('product_version',['product_id'=>$product['id'],'version_label'=>'offline-v1','notes'=>wp_json_encode($notes)]);self::assertNotWPError($version);self::assertNotWPError($products->transition('product_version',(int)$version['id'],'REVIEW'));self::assertNotWPError($products->transition('product_version',(int)$version['id'],'APPROVED'));return $version;
 }
 public static function shops():array{return [['digital'],['personalized_pod'],['standard_pod'],['jewelry']];}
 /** @dataProvider shops */
 public function testListingAndReceivedOrderCannotCrossShopOwnership(string $shop):void {
  $version=$this->version($shop);$listing=(new DigiForge\Listings\Repository())->createListing(['product_version_id'=>$version['id'],'environment'=>'sandbox','channel'=>'etsy','shop_reference'=>$shop,'title'=>'Offline fixture','description'=>'No live listing','price_amount'=>12,'currency'=>'USD']);self::assertNotWPError($listing);$orders=new DigiForge\Orders\Repository();foreach(['digital','personalized_pod','standard_pod','jewelry']as $other){$order=$orders->createOrder(['shop_reference'=>$other,'channel'=>'etsy','environment'=>'sandbox']);self::assertNotWPError($order);$line=$orders->addLineItem(['order_id'=>$order['id'],'listing_id'=>$listing['id'],'product_version_id'=>$version['id']]);if($other===$shop){self::assertNotWPError($line);self::assertFalse($orders->readiness((int)$order['id'])['ready']);}else self::assertWPError($line);}
  self::assertTrue(DigiForge\Core\Settings::safety_locked());self::assertTrue(DigiForge\Core\Settings::get('stop_all',true));self::assertFalse(DigiForge\Core\Settings::get('automation_armed',false));
 }
 public function testReadinessRechecksCurrentListingOwnership():void {
  $version=$this->version('digital');$listing=(new DigiForge\Listings\Repository())->createListing(['product_version_id'=>$version['id'],'environment'=>'sandbox','channel'=>'etsy','shop_reference'=>'digital','title'=>'Offline current lineage','description'=>'Fixture','price_amount'=>12,'currency'=>'USD']);self::assertNotWPError($listing);$orders=new DigiForge\Orders\Repository();$order=$orders->createOrder(['shop_reference'=>'digital','channel'=>'etsy','environment'=>'sandbox']);self::assertNotWPError($order);self::assertNotWPError($orders->addLineItem(['order_id'=>$order['id'],'listing_id'=>$listing['id'],'product_version_id'=>$version['id']]));self::assertTrue($orders->readiness((int)$order['id'])['checks']['line_items_valid']);
  global $wpdb;foreach(['DIGITAL','digital ','jewelry'] as $drift){self::assertSame(1,$wpdb->update(DigiForge\Database\Tables::listings(),['shop_reference'=>$drift],['id'=>$listing['id']]));self::assertFalse($orders->readiness((int)$order['id'])['checks']['line_items_valid']);}
 }
 public function testOrderRejectsListingChannelAndEnvironmentMismatch():void {
  $version=$this->version('digital');$listings=new DigiForge\Listings\Repository();$orders=new DigiForge\Orders\Repository();
  foreach([['shopify','sandbox'],['etsy','production']] as [$channel,$environment]){
   $listing=$listings->createListing(['product_version_id'=>$version['id'],'environment'=>$environment,'channel'=>'etsy','shop_reference'=>'digital','title'=>'Offline boundary','description'=>'Fixture only','price_amount'=>12,'currency'=>'USD']);self::assertNotWPError($listing);
   if($channel!=='etsy'){global $wpdb;$wpdb->update(DigiForge\Database\Tables::listings(),['channel'=>$channel],['id'=>$listing['id']]);}
   $order=$orders->createOrder(['shop_reference'=>'digital','channel'=>'etsy','environment'=>'sandbox']);self::assertNotWPError($order);
   self::assertWPError($orders->addLineItem(['order_id'=>$order['id'],'listing_id'=>$listing['id'],'product_version_id'=>$version['id']]));
  }
 }
 public function testDigitalDesignReleaseToListingPreservesReviewedShopAndSandbox():void {
  $version=$this->version('digital');$production=new DigiForge\Production\Repository();$spec=$production->createSpec(['product_version_id'=>$version['id'],'asset_key'=>'offline-art','asset_type'=>'digital','format'=>'png','width_px'=>4,'height_px'=>4,'dpi'=>300]);self::assertNotWPError($spec);$plan=$production->createPlan(['product_version_id'=>$version['id'],'plan_key'=>'offline-design','version_label'=>'1','channel'=>'digital','production_type'=>'artwork']);self::assertNotWPError($plan);self::assertTrue($production->linkAsset((int)$plan['id'],(int)$spec['id']));$intent=$production->createIntent(['production_plan_id'=>$plan['id'],'asset_spec_id'=>$spec['id'],'intent_type'=>'RENDER','provider_class'=>'ai','input_payload'=>['prompt_ref'=>'offline-reviewed-spec']]);self::assertNotWPError($intent);self::assertSame('BLOCKED',$intent['state']);
  $pixels=str_repeat("\xff\xff\xff\xff",16);$png=DigiForge\POD\RasterArtworkCodec::encode(4,4,$pixels);$decoded=DigiForge\POD\RasterArtworkCodec::decode($png);self::assertSame($pixels,$decoded['rgba']);$path=tempnam(sys_get_temp_dir(),'df-offline-release-');try{file_put_contents($path,$png);$revision=$production->addRevision(['asset_spec_id'=>$spec['id'],'revision_label'=>'r1','storage_reference'=>'local://offline-fixture/art.png','checksum_sha256'=>hash('sha256',file_get_contents($path)),'mime_type'=>'image/png','byte_size'=>strlen($png),'width_px'=>4,'height_px'=>4,'provenance'=>['origin'=>'offline_acceptance_fixture','pixel_sha256'=>$decoded['pixel_sha256']]]);self::assertNotWPError($revision);self::assertNotWPError($production->addQa(['target_type'=>'revision','target_id'=>$revision['id'],'check_type'=>'decoded_pixels','status'=>'PASS','details'=>['fixture_only'=>true,'pixel_sha256'=>$decoded['pixel_sha256']]]));foreach(['QA_PASSED','APPROVED']as $state)self::assertNotWPError($production->transition('revision',(int)$revision['id'],$state));foreach(['VALIDATED','REVIEW_REQUIRED','APPROVED']as $state)self::assertNotWPError($production->transition('plan',(int)$plan['id'],$state));$bundle=$production->createBundle(['production_plan_id'=>$plan['id'],'bundle_key'=>'offline-release','version_label'=>'1']);self::assertNotWPError($bundle);foreach(['VALIDATED','REVIEW_REQUIRED','APPROVED']as $state)self::assertNotWPError($production->transition('bundle',(int)$bundle['id'],$state));self::assertSame('RELEASE_READY',$production->validateBundle((int)$bundle['id'])['state']);
   $factory=new DigiForge\Listings\ListingFactory();$result=$factory->prepare((int)$version['id'],'offline-listing');self::assertNotWPError($result);self::assertSame('digital',$result['listing']['shop_reference']);self::assertSame('sandbox',$result['listing']['environment']);self::assertSame('REVIEW_REQUIRED',$result['listing']['state']);self::assertSame($result['listing_id'],$factory->prepare((int)$version['id'],'offline-listing')['listing_id']);self::assertFalse($result['draft_package_created']);global $wpdb;self::assertGreaterThan(0,(int)$wpdb->get_var($wpdb->prepare('SELECT COUNT(*) FROM '.DigiForge\Database\Tables::audit_log().' WHERE object_type=%s AND object_id=%s','listing',(string)$result['listing_id'])));
  }finally{unlink($path);}
 }
}
